alter table public.minisites
 add column if not exists start_date date, add column if not exists end_date date, add column if not exists event_format text, add column if not exists location text, add column if not exists organizer text,
 add column if not exists navbar_brand text, add column if not exists navbar_button_label text,
 add column if not exists hero_eyebrow text, add column if not exists hero_title text, add column if not exists hero_description text, add column if not exists hero_primary_cta text, add column if not exists hero_secondary_cta text, add column if not exists hero_image_url text, add column if not exists hero_image_alt text,
 add column if not exists materi_heading text, add column if not exists schedule_heading text, add column if not exists speakers_heading text, add column if not exists pricing_heading text,
 add column if not exists registration_heading text, add column if not exists registration_description text, add column if not exists registration_button_label text, add column if not exists admin_whatsapp text,
 add column if not exists footer_organization text, add column if not exists footer_address text, add column if not exists footer_whatsapp text, add column if not exists footer_email text,
 add column if not exists sticky_cta_text text, add column if not exists sticky_cta_button_label text,
 add column if not exists seo_meta_title text, add column if not exists seo_meta_description text, add column if not exists seo_og_image_url text, add column if not exists seo_canonical_url text, add column if not exists theme_primary_color text default '#0F172A';
create table if not exists public.minisite_materials (id uuid primary key default gen_random_uuid(), minisite_id uuid not null references public.minisites(id) on delete cascade, title text not null, description text, sort_order integer not null default 0, created_at timestamptz not null default now());
create table if not exists public.minisite_agenda (id uuid primary key default gen_random_uuid(), minisite_id uuid not null references public.minisites(id) on delete cascade, day_label text, time_label text, title text not null, description text, sort_order integer not null default 0, created_at timestamptz not null default now());
create table if not exists public.minisite_speakers (id uuid primary key default gen_random_uuid(), minisite_id uuid not null references public.minisites(id) on delete cascade, name text not null, role text, bio text, topic text, image_url text, sort_order integer not null default 0, created_at timestamptz not null default now());
create table if not exists public.minisite_pricing (id uuid primary key default gen_random_uuid(), minisite_id uuid not null references public.minisites(id) on delete cascade, name text not null, description text, original_price numeric(14,2), price numeric(14,2) not null default 0, unit_label text, badge text, features text[] not null default '{}', button_label text, is_featured boolean not null default false, sort_order integer not null default 0, created_at timestamptz not null default now());
create index if not exists idx_minisite_materials_order on public.minisite_materials(minisite_id,sort_order);
create index if not exists idx_minisite_agenda_order on public.minisite_agenda(minisite_id,sort_order);
create index if not exists idx_minisite_speakers_order on public.minisite_speakers(minisite_id,sort_order);
create index if not exists idx_minisite_pricing_order on public.minisite_pricing(minisite_id,sort_order);
alter table public.minisite_materials enable row level security; alter table public.minisite_agenda enable row level security; alter table public.minisite_speakers enable row level security; alter table public.minisite_pricing enable row level security;
create policy "Public can read materials of published minisites" on public.minisite_materials for select to anon, authenticated using (exists(select 1 from public.minisites m where m.id=minisite_id and m.status='published'));
create policy "Public can read agenda of published minisites" on public.minisite_agenda for select to anon, authenticated using (exists(select 1 from public.minisites m where m.id=minisite_id and m.status='published'));
create policy "Public can read speakers of published minisites" on public.minisite_speakers for select to anon, authenticated using (exists(select 1 from public.minisites m where m.id=minisite_id and m.status='published'));
create policy "Public can read pricing of published minisites" on public.minisite_pricing for select to anon, authenticated using (exists(select 1 from public.minisites m where m.id=minisite_id and m.status='published'));
grant select on public.minisite_materials, public.minisite_agenda, public.minisite_speakers, public.minisite_pricing to anon, authenticated;